content:
/* Counterfeit · 开场白挂载器
   机制：酒馆助手脚本在独立沙箱执行，UI 必须挂载到宿主文档（window.top.document）；
   同时检查宿主 0 楼锚点与原始 <OpeningUI/> 消息，避免局部正则失效时静默黑屏；
   发现未完成的开局 → 创建全屏 srcdoc iframe（内嵌 dist 单文件 + API 桥前置注入）；
   commit 后占位符被替换、原始开局消息消失 → 自动卸载 iframe，无需刷新页面；
   commit 完成时 iframe 发 postMessage(commit-done)，由本脚本（持久沙箱上下文）编排
   首条回复：插入可见 user 消息 → 复制 0 楼变量基线 → /trigger（避免与楼层刷新/卸载竞态）。 */
console.info('[Counterfeit·开场白] eval');
(() => {
  const IFRAME_ID = 'counterfeit-opening-iframe';
  const ANCHOR_SELECTOR = '#counterfeit-opening-anchor';
  const SANDBOX_NAME = '__counterfeit_sandbox__';
  const EMBEDDED_HTML_B64 = '';
  const EMBEDDED_HTML = new TextDecoder().decode(
    Uint8Array.from(atob(EMBEDDED_HTML_B64), char => char.charCodeAt(0)),
  );

  // API 桥：开场白 iframe 的 parent 是宿主页面（没有酒馆 API），
  // 真正的 API 在酒馆助手脚本沙箱里——本脚本把它命名为 __counterfeit_sandbox__。
  window.name = SANDBOX_NAME;
  // 酒馆助手也会以词法变量注入 API；显式公布给 srcdoc，不能只读 sandbox.window[key]。
  window.__counterfeit_opening_api__ = {
    getVariables: typeof getVariables === 'function' ? getVariables : undefined,
    updateVariablesWith: typeof updateVariablesWith === 'function' ? updateVariablesWith : undefined,
    insertOrAssignVariables: typeof insertOrAssignVariables === 'function' ? insertOrAssignVariables : undefined,
    deleteVariable: typeof deleteVariable === 'function' ? deleteVariable : undefined,
    getChatMessages: typeof getChatMessages === 'function' ? getChatMessages : undefined,
    setChatMessages: typeof setChatMessages === 'function' ? setChatMessages : undefined,
    createChatMessages: typeof createChatMessages === 'function' ? createChatMessages : undefined,
    getLastMessageId: typeof getLastMessageId === 'function' ? getLastMessageId : undefined,
    getModelList: typeof getModelList === 'function' ? getModelList : undefined,
    waitGlobalInitialized: typeof waitGlobalInitialized === 'function' ? waitGlobalInitialized : undefined,
    eventOn: typeof eventOn === 'function' ? eventOn : undefined,
    eventMakeFirst: typeof eventMakeFirst === 'function' ? eventMakeFirst : undefined,
    eventEmit: typeof eventEmit === 'function' ? eventEmit : undefined,
    tavern_events: typeof tavern_events !== 'undefined' ? tavern_events : undefined,
    _: typeof _ !== 'undefined' ? _ : undefined,
    $: typeof $ === 'function' ? $ : undefined,
    jQuery: typeof jQuery === 'function' ? jQuery : undefined,
  };
  const BRIDGE = `<script>
(function () {
  var names = [
    "getVariables", "updateVariablesWith", "insertOrAssignVariables", "deleteVariable",
    "getChatMessages", "setChatMessages", "createChatMessages", "getLastMessageId",
    "waitGlobalInitialized", "getModelList",
    "eventOn", "eventMakeFirst", "eventEmit", "tavern_events", "_", "$", "jQuery"
  ];

  function pick(host) {
    if (!host) return;
    var registry = host.__counterfeit_opening_api__ || host;
    for (var i = 0; i < names.length; i++) {
      var key = names[i];
      try {
        var value = typeof registry[key] !== "undefined" ? registry[key] : host[key];
        if (typeof window[key] === "undefined" && typeof value !== "undefined") {
          // lodash/jQuery 本身也是函数，bind 会丢失 _.get/_.set/$.fn 等静态成员。
          window[key] = typeof value === "function" && ["_", "$", "jQuery"].indexOf(key) === -1 ? value.bind(host) : value;
        }
      } catch (error) {}
    }
  }

  function findOpeningBlock(messages) {
    if (!Array.isArray(messages)) return null;
    for (var i = 0; i < messages.length; i++) {
      var item = messages[i];
      if (item && item.message_id === 0 && typeof item.message === "string") {
        var match = item.message.match(/<opening_setup\\b[\\s\\S]*?<\\/opening_setup>/);
        if (match) return match[0];
      }
    }
    return null;
  }

  function installBootWatchdog() {
    document.addEventListener("DOMContentLoaded", function () {
      var app = document.getElementById("app");
      var watchdog = document.createElement("div");
      watchdog.id = "counterfeit-opening-watchdog";
      // 老旧 X5/WebKit 内核不支持 inset 简写，且 cssText 遇到无效声明会截断后续解析；
      // left/top/right/bottom/width/height 分开写，老内核全部认识，不会丢声明
      watchdog.style.cssText = [
        "position:fixed", "left:0", "top:0", "right:0", "bottom:0",
        "width:100%", "height:100%", "z-index:2147483647",
        "display:flex", "align-items:center", "justify-content:center",
        "padding:24px", "background:#171319", "color:#f7eef3",
        "font:14px/1.8 sans-serif", "text-align:center"
      ].join(";");
      watchdog.textContent = "Counterfeit 开场白正在加载……";
      document.body.appendChild(watchdog);

      var startedAt = Date.now();
      var timer = setInterval(function () {
        if (app && app.childElementCount > 0) {
          clearInterval(timer);
          watchdog.remove();
          return;
        }
        if (Date.now() - startedAt > 8000) {
          clearInterval(timer);
          watchdog.textContent = "Counterfeit 开场白加载失败。请检查酒馆助手日志与外部模块访问设置。";
        }
      }, 100);
    }, { once: true });
  }

  function withoutOpeningBlock(messages, block) {
    return messages.map(function (item) {
      if (!item || item.message_id !== 0 || typeof item.message !== "string") return item;
      var copy = Object.assign({}, item);
      copy.message = copy.message
        .replace(block, "")
        .replace(/\\n{3,}/g, "\\n\\n")
        .trim();
      return copy;
    });
  }

  try {
    installBootWatchdog();
    var host = window.parent;
    if (!host || host === window) return;
    var sandbox = null;
    try {
      for (var i = 0; i < host.frames.length; i++) {
        var frame = host.frames[i];
        try {
          if (frame && frame.__counterfeit_opening_api__) {
            sandbox = frame;
            break;
          }
        } catch (error) {}
      }
    } catch (error) {}
    if (!sandbox) {
      try { sandbox = host.frames["${SANDBOX_NAME}"]; } catch (error) {}
    }
    pick(sandbox || host);

    // 新版 commit（dist 内）已完整负责：MVU 变量全量写入（含初始关系预建）、
    // 0 楼落盘。本拦截器只把 <opening_setup> 块从 0 楼剥离，
    // 避免开局元数据明文残留正文；
    // 不再 normalize 变量 / 不再伪造 user 消息 / 不再 /trigger——
    // 旧流程会把 commit 预建的 characters 清空并重复触发生成（剧情模式开局关系归零的根因）。
    var rawSetChatMessages = window.setChatMessages;
    if (typeof rawSetChatMessages === "function") {
      window.setChatMessages = function (messages, options) {
        var block = findOpeningBlock(messages);
        if (!block) return rawSetChatMessages(messages, options);
        return rawSetChatMessages(withoutOpeningBlock(messages, block), options);
      };
    }
  } catch (error) {
    console.error("[Counterfeit Opening] bridge error", error);
  }
})();
<\/script>`;

  function getHostDocument() {
    try {
      return window.top?.document ?? window.parent?.document ?? document;
    } catch (error) {
      console.error('[Counterfeit·开场白] 无法访问宿主文档：', error);
      return document;
    }
  }

  const topDoc = getHostDocument();

  // —— 开局文字降级（防黑屏）——
  // 任何"应该挂载但挂不出来"的分支都必须留下可见文字，而不是只写 console。
  // 三项自检：插件（酒馆助手 API）/ 脚本（内嵌界面 HTML）/ 正则（0 楼占位符替换）。
  const NOTICE_ID = 'counterfeit-opening-fallback';

  function isUsableOpeningHtml(html) {
    return typeof html === 'string' && html.length > 1024 && /<(?:!doctype|html|body|div)\b/i.test(html);
  }

  // 酒馆助手 API 注入到脚本沙箱作用域，不一定挂在 window 上——
  // 用与本文件其余检测一致的裸标识符 typeof，避免误报"缺少 API"。
  function missingOpeningApis() {
    const probes = [
      ['getChatMessages', () => typeof getChatMessages],
      ['getLastMessageId', () => typeof getLastMessageId],
      ['getVariables', () => typeof getVariables],
      ['createChatMessages', () => typeof createChatMessages],
    ];
    return probes
      .filter(([, probe]) => {
        try {
          return probe() !== 'function';
        } catch (error) {
          return true;
        }
      })
      .map(([name]) => name);
  }

  function selfCheck() {
    const missingApis = missingOpeningApis();
    const hasAnchor = Boolean(topDoc.querySelector(ANCHOR_SELECTOR));
    const rawPending = rawGreetingNeedsOpening();
    let embedded = null;
    try {
      embedded = typeof EMBEDDED_HTML === 'string' ? EMBEDDED_HTML : null;
    } catch (error) {
      embedded = null;
    }

    return [
      {
        name: '插件',
        ok: missingApis.length === 0,
        detail:
          missingApis.length === 0
            ? '酒馆助手 API 就绪'
            : '缺少 API：' + missingApis.join('、') + '——请确认已启用酒馆助手（JS-Slash-Runner）并允许本卡运行脚本',
      },
      {
        name: '脚本',
        ok: embedded === null ? true : isUsableOpeningHtml(embedded),
        detail:
          embedded === null
            ? '未内嵌界面（走远端拉取）——若拉取失败请检查网络/CSP'
            : isUsableOpeningHtml(embedded)
              ? '内嵌界面 HTML 完整（' + embedded.length + ' 字符）'
              : '内嵌界面 HTML 缺失或被截断——请重新运行 build_tools/pack_embedded_frontends.py 并重新导入卡',
      },
      {
        name: '正则',
        ok: hasAnchor || !rawPending,
        detail: hasAnchor
          ? '0 楼锚点已就位'
          : rawPending
            ? '未找到锚点，已用 0 楼原文兜底——请确认正则「开场白界面」与「对AI隐藏开场白界面」均已启用且未被局部正则覆盖'
            : '开局已完成，无需锚点',
      },
    ];
  }

  function clearFallbackNotice() {
    const existing = topDoc.getElementById(NOTICE_ID);
    if (existing) existing.remove();
  }

  function renderFallbackNotice(reason) {
    if (!topDoc.body) {
      console.error('[Counterfeit·开场白] 宿主 body 不可用，无法输出降级提示');
      return;
    }
    const checks = selfCheck();
    const lines = checks.map(item => (item.ok ? '✅ ' : '❌ ') + item.name + '：' + item.detail);
    const headline =
      reason === 'script'
        ? '开场白界面无法加载（内嵌界面缺失）'
        : reason === 'host'
          ? '开场白界面无法挂载（宿主页面未就绪）'
          : reason === 'regex'
            ? '开场白界面未能显示（0 楼占位符未被替换）'
            : '开场白界面未能显示';

    console.error('[Counterfeit·开场白] 降级提示：' + headline + '\n' + lines.join('\n'));

    let box = topDoc.getElementById(NOTICE_ID);
    if (!box) {
      box = topDoc.createElement('div');
      box.id = NOTICE_ID;
      // 与 watchdog 同理：不用 inset 简写（老内核不支持且会截断 cssText 解析），
      // 这是最后的可见降级通道，它自己都铺不满屏就什么都看不到了
      box.style.cssText = [
        'position:fixed',
        'left:0',
        'top:0',
        'right:0',
        'bottom:0',
        'width:100%',
        'height:100%',
        'z-index:1000000',
        'overflow:auto',
        'display:flex',
        'align-items:center',
        'justify-content:center',
        'padding:24px',
        'background:#171319',
        'color:#f7eef3',
        'font:14px/1.9 sans-serif',
      ].join(';');
      topDoc.body.appendChild(box);
    }

    const panel = topDoc.createElement('div');
    panel.style.cssText = 'max-width:560px;width:100%;text-align:left;';

    const title = topDoc.createElement('div');
    title.style.cssText = 'font-size:16px;font-weight:700;margin-bottom:12px;';
    title.textContent = 'Counterfeit · ' + headline;
    panel.appendChild(title);

    const list = topDoc.createElement('div');
    list.style.cssText = 'white-space:pre-wrap;margin-bottom:16px;';
    list.textContent = lines.join('\n');
    panel.appendChild(list);

    const hint = topDoc.createElement('div');
    hint.style.cssText = 'opacity:.75;margin-bottom:16px;';
    hint.textContent =
      '修好上面标 ❌ 的项后刷新页面即可重新进入开场白。若三项均为 ✅ 仍看不到界面，请查看控制台 [Counterfeit·开场白] 日志。也可关闭本提示手动发送第一条消息直接开始（此时不会写入开局变量）。';
    panel.appendChild(hint);

    const dismiss = topDoc.createElement('button');
    dismiss.type = 'button';
    dismiss.textContent = '关闭提示';
    dismiss.style.cssText =
      'padding:8px 18px;border:1px solid rgba(247,238,243,.4);border-radius:6px;background:transparent;color:inherit;cursor:pointer;font:inherit;';
    dismiss.addEventListener('click', () => {
      noticeDismissed = true;
      clearFallbackNotice();
    });
    panel.appendChild(dismiss);

    box.textContent = '';
    box.appendChild(panel);
  }

  let noticeDismissed = false;

  function rawGreetingNeedsOpening() {
    if (typeof getChatMessages !== 'function') return false;
    try {
      const messages = getChatMessages(0);
      return (
        Array.isArray(messages) &&
        messages.some(
          item =>
            item &&
            item.message_id === 0 &&
            typeof item.message === 'string' &&
            item.message.includes('<OpeningUI/>'),
        )
      );
    } catch (error) {
      console.warn('[Counterfeit·开场白] 读取 0 楼原始消息失败：', error);
      return false;
    }
  }

  // —— 开场白 iframe 尺寸校准（与状态栏 syncOverlaySize 同源思路）——
  // 【移动端定位：不用 inset/vw/vh，用 JS 实测像素】
  // 老旧 X5/WebKit 内核不支持 inset 简写，且 cssText 遇到无效声明会从该处截断解析，
  // 'position:fixed;inset:0;width:100vw;height:100vh;…' 会让尺寸声明整段丢失，
  // iframe 退化为默认固有尺寸（约 300×150）停在挂载瞬间的位置——移动端开场白缩成
  // 小盒压在左上角的根因。酒馆的 html 带 perspective（fixed 包含块不是视口），
  // 位置一律用像素 left/top：cssText 只写老内核一定认识的声明，
  // left/top/width/height 全部由 syncOpeningSize() 写实测像素。
  function openingViewport() {
    // 实测可见视口：visualViewport 最准（排除地址栏/软键盘，offset 处理双指缩放偏移），
    // 逐级回退 documentElement.clientWidth/Height → innerWidth/innerHeight
    try {
      const vv = window.top.visualViewport;
      if (vv && vv.width > 0 && vv.height > 0) {
        return {
          width: Math.round(vv.width),
          height: Math.round(vv.height),
          offsetLeft: Math.round(vv.offsetLeft || 0),
          offsetTop: Math.round(vv.offsetTop || 0),
        };
      }
    } catch (error) {}
    try {
      const docEl = topDoc.documentElement;
      if (docEl && docEl.clientWidth > 0 && docEl.clientHeight > 0) {
        return { width: docEl.clientWidth, height: docEl.clientHeight, offsetLeft: 0, offsetTop: 0 };
      }
    } catch (error) {}
    try {
      if (window.top.innerWidth > 0 && window.top.innerHeight > 0) {
        return { width: window.top.innerWidth, height: window.top.innerHeight, offsetLeft: 0, offsetTop: 0 };
      }
    } catch (error) {}
    return { width: 0, height: 0, offsetLeft: 0, offsetTop: 0 };
  }

  function syncOpeningSize() {
    const iframe = topDoc.getElementById(IFRAME_ID);
    if (!iframe) return;
    const vp = openingViewport();
    if (vp.width <= 0 || vp.height <= 0) return;
    iframe.style.left = vp.offsetLeft + 'px';
    iframe.style.top = vp.offsetTop + 'px';
    iframe.style.width = vp.width + 'px';
    iframe.style.height = vp.height + 'px';
  }

  // 跟随地址栏收放/旋屏/软键盘/双指缩放持续校准；iframe 卸载时解绑（见 check() 卸载分支）
  let openingViewportBound = false;
  function bindOpeningViewportListeners() {
    if (openingViewportBound) return;
    openingViewportBound = true;
    try {
      window.top.addEventListener('resize', syncOpeningSize);
      window.top.addEventListener('orientationchange', syncOpeningSize);
      const vv = window.top.visualViewport;
      if (vv) {
        vv.addEventListener('resize', syncOpeningSize);
        vv.addEventListener('scroll', syncOpeningSize);
      }
    } catch (error) {}
  }

  function unbindOpeningViewportListeners() {
    if (!openingViewportBound) return;
    openingViewportBound = false;
    try {
      window.top.removeEventListener('resize', syncOpeningSize);
      window.top.removeEventListener('orientationchange', syncOpeningSize);
      const vv = window.top.visualViewport;
      if (vv) {
        vv.removeEventListener('resize', syncOpeningSize);
        vv.removeEventListener('scroll', syncOpeningSize);
      }
    } catch (error) {}
  }

  let mountingPromise = null;
  function buildAndMount() {
    if (topDoc.getElementById(IFRAME_ID)) return Promise.resolve();
    if (mountingPromise) return mountingPromise;
    const epoch = chatEpoch;
    let expired = false;
    let timeoutId;
    const current = () => !expired && epoch === chatEpoch;
    const deadline = new Promise((_resolve, reject) => {
      timeoutId = setTimeout(() => {
        expired = true;
        reject(new Error('开场白界面读取超时，请重试加载'));
      }, 15000);
    });
    const pending = Promise.race([mountOpening(epoch, current), deadline]).catch(error => {
      console.error('[Counterfeit·开场白] 界面挂载失败：', error);
      if (epoch === chatEpoch && !noticeDismissed) renderFallbackNotice('script');
    }).finally(() => {
      clearTimeout(timeoutId);
      if (mountingPromise === pending) mountingPromise = null;
    });
    mountingPromise = pending;
    return pending;
  }

  async function mountOpening(epoch, current) {
    if (topDoc.getElementById(IFRAME_ID)) return;
    const html = EMBEDDED_HTML;
    // 远端读取可能晚于换聊天或提交；过期 HTML 不得重新盖住当前聊天。
    if (!current() || resumeCommitted || topDoc.getElementById(IFRAME_ID)) return;
    if (!topDoc.querySelector(ANCHOR_SELECTOR) && !rawGreetingNeedsOpening()) return;
    if (!isUsableOpeningHtml(html)) {
      console.error('[Counterfeit·开场白] 界面 HTML 不可用（缺失或被截断）');
      if (!noticeDismissed) renderFallbackNotice('script');
      return;
    }
    const iframe = topDoc.createElement('iframe');
    iframe.id = IFRAME_ID;
    // cssText 只写老内核一定认识的声明（不用 inset/vw/vh，原因见上方 openingViewport 注释）；
    // left/top 给 0 作初始值，尺寸由 appendChild 后的 syncOpeningSize() 写实测像素
    iframe.style.cssText = 'position:fixed;left:0;top:0;border:none;z-index:999999;background:#fff;';
    iframe.srcdoc = BRIDGE + html;
    if (!topDoc.body) {
      console.error('[Counterfeit·开场白] 宿主 body 尚未就绪');
      if (!noticeDismissed) renderFallbackNotice('host');
      return;
    }
    topDoc.body.appendChild(iframe);
    syncOpeningSize();
    bindOpeningViewportListeners();
    // 挂载后自检：老内核若仍没吃上尺寸，getBoundingClientRect 会暴露——
    // 宽或高不足实测视口 60% 视为定位失败，按像素法重试一次；
    // 仍失败则给可见降级提示，绝不允许静默缩成小盒
    setTimeout(() => {
      const mounted = topDoc.getElementById(IFRAME_ID);
      if (!mounted) return;
      const vp = openingViewport();
      if (vp.width <= 0 || vp.height <= 0) return;
      const rect = mounted.getBoundingClientRect();
      if (rect.width >= vp.width * 0.6 && rect.height >= vp.height * 0.6) return;
      console.warn(
        '[Counterfeit·开场白] iframe 尺寸自检未过（' +
          Math.round(rect.width) + '×' + Math.round(rect.height) +
          ' / 视口 ' + vp.width + '×' + vp.height + '），按实测像素重试',
      );
      syncOpeningSize();
      setTimeout(() => {
        const retried = topDoc.getElementById(IFRAME_ID);
        if (!retried) return;
        const retryRect = retried.getBoundingClientRect();
        if (retryRect.width >= vp.width * 0.6 && retryRect.height >= vp.height * 0.6) return;
        console.error('[Counterfeit·开场白] iframe 定位重试仍失败，转入降级提示');
        if (!noticeDismissed) renderFallbackNotice('host');
      }, 500);
    }, 1500);
    clearFallbackNotice();
    console.info('[Counterfeit·开场白] 已挂载');
  }

  function check() {
    const anchor = topDoc.querySelector(ANCHOR_SELECTOR);
    const iframe = topDoc.getElementById(IFRAME_ID);
    const shouldMount = !resumeCommitted && (Boolean(anchor) || rawGreetingNeedsOpening());
    if (shouldMount && !iframe) {
      void buildAndMount();
    } else if (!shouldMount && iframe) {
      unbindOpeningViewportListeners();
      iframe.remove();
      console.info('[Counterfeit·开场白] 开局占位符消失，已卸载');
    }
    // 兜底通道：commit 完成检测（与 iframe 卸载同周期轮询）
    detectCommitDone();
  }

  // —— 开局首条回复编排（脚本库沙箱 = 持久上下文，不受开场白 iframe 卸载影响）——
  // 双通道触发：commit 时 iframe postMessage(commit-done) 为快速通道；
  // check() 轮询检测为兜底通道（0 楼占位符消失 + 变量已提交 + 仍只有 0 楼 + 未触发过）。
  // 编排（阶段C/T4）：开局任务状态机（opening_runtime，chat 级权威 + 0 楼镜像）——
  //   preparing → ready → generating → completed；失败记录 failed+last_error 且可重试。
  // 就绪闸（O03）：有可用方案（基础/增强）才 /trigger；自建主线无方案绝不静默走 J 班默认入口。
  // 增强握手（§4.3）：先订阅 counterfeit_opening_adapter_ready 再发 request（携带任务身份）；
  //   30s 未返回给「继续等待 / 使用基础开局 / 重试」；选定基础后迟到增强不得改写本轮。
  // 完成判定（⑥）：以对应 assistant 消息确实存在且内容有效为准；/trigger 被调用不等于完成。
  // 硬性约束：user 楼层不存在时绝不 /trigger（否则会打在 0 楼上生成空 swipe）。
  let orchestratingToken = null; // 同进程并发入口闩（代次化）：CHAT_CHANGED 强释后，旧编排 finally 不得清掉新编排的闩
  let chatEpoch = 0; // 换聊天作废旧编排（旧任务结果绝不写进新聊天）
  let phoneAdapterAnnounced = false; // 手机解析服务已宣告（换聊天重置；未宣告直接采用基础方案）
  let openingReadySubscribed = false;
  let openingWatchTimer = null; // 首条回复落地监视（单轮唯一）
  let openingWatchTicks = 0;
  let openingPromptAbort = null; // 换聊天时强制解散等待面板
  let lastOpeningCommitKind = null;
  const openingWaiters = new Map(); // session_id → { resolve, fingerprint }，仅活跃等待认领结果
  const failedAutoRetries = {}; // 轮询对 failed 的自动重试计数（有上限）

  const OPENING_ENHANCE_WAIT_MS = 30000; // §3.5：30 秒是交互提示点，不动 300s 模型调用上限
  const OPENING_WATCH_INTERVAL_MS = 1000;
  const OPENING_WATCH_TIMEOUT_MS = 300000;
  const OPENING_FAILED_POLL_RETRY_MAX = 3;
  // 状态机白名单：只允许这些转换；completed 为终态，failed 只能经 preparing 重试
  const OPENING_PHASE_TRANSITIONS = {
    preparing: ['ready', 'failed'],
    ready: ['preparing', 'generating', 'failed'],
    generating: ['completed', 'failed'],
    completed: [],
    failed: ['preparing'],
  };

  function validOpeningRuntime(rt) {
    return (
      !!rt &&
      typeof rt === 'object' &&
      rt.schema_version === 1 &&
      typeof rt.session_id === 'string' &&
      rt.session_id.length > 0
    );
  }
  function readChatOpeningRuntime() {
    if (typeof getVariables !== 'function') return null;
    try {
      const rt = ((getVariables({ type: 'chat' }) || {}).stat_data || {}).opening_runtime;
      return validOpeningRuntime(rt) ? rt : null;
    } catch (error) {
      return null;
    }
  }
  function readFloorOpeningRuntime(messageId) {
    if (typeof getVariables !== 'function') return null;
    try {
      const rt = ((getVariables({ type: 'message', message_id: messageId }) || {}).stat_data || {}).opening_runtime;
      return validOpeningRuntime(rt) ? rt : null;
    } catch (error) {
      return null;
    }
  }
  /** 开局任务读取：chat 级权威，0 楼镜像兜底（兼容 chat 桶缺失的旧环境） */
  function readOpeningRuntime() {
    return readChatOpeningRuntime() || readFloorOpeningRuntime(0);
  }

  /** 仅当前任务可写回：只改 session_id 匹配的 scope（chat + 0 楼 + 末楼镜像），updater 返回 null 表示拒绝 */
  async function patchOpeningRuntime(sessionId, updater) {
    if (typeof updateVariablesWith !== 'function' || typeof getLastMessageId !== 'function') return null;
    const lastId = getLastMessageId();
    const current = readOpeningRuntime();
    const userFloorId = current && current.session_id === sessionId ? current.user_message_id : null;
    const scopes = [{ type: 'chat' }];
    const seen = { chat: true };
    for (const id of [0, lastId, userFloorId]) {
      if (id == null) continue;
      const key = 'm' + id;
      if (seen[key]) continue;
      seen[key] = true;
      scopes.push({ type: 'message', message_id: id });
    }
    for (const scope of scopes) {
      await updateVariablesWith(
        vars => {
          const stat = vars && vars.stat_data;
          const rt = stat && stat.opening_runtime;
          if (!validOpeningRuntime(rt) || rt.session_id !== sessionId) return vars;
          const patched = updater(JSON.parse(JSON.stringify(rt)));
          if (!patched) return vars;
          stat.opening_runtime = patched;
          return vars;
        },
        scope,
      );
    }
    return readOpeningRuntime();
  }

  /** 状态机转换：白名单外的转换一律拒绝；成功返回新 runtime，失败返回 null */
  async function transitionOpeningPhase(sessionId, to, extra) {
    const current = readOpeningRuntime();
    if (!current || current.session_id !== sessionId) return null;
    const allowed = OPENING_PHASE_TRANSITIONS[current.phase] || [];
    await patchOpeningRuntime(sessionId, rt => {
      if (rt.phase !== to && allowed.indexOf(to) === -1) return null;
      const merged = Object.assign({}, rt, extra || {});
      merged.phase = to;
      merged.schema_version = 1;
      merged.session_id = sessionId;
      return merged;
    });
    const next = readOpeningRuntime();
    if (!next || next.session_id !== sessionId || next.phase !== to) {
      console.warn('[Counterfeit·开场白] 开局状态转换被拒绝：' + current.phase + ' → ' + to);
      return null;
    }
    return next;
  }

  /** 旧档无 session_id 时的受限兼容：创建 legacy 任务并写入 chat + 0 楼（已存在其他会话任务则不覆盖） */
  async function putOpeningRuntime(runtime) {
    if (typeof updateVariablesWith !== 'function') return false;
    let wrote = false;
    for (const scope of [{ type: 'chat' }, { type: 'message', message_id: 0 }]) {
      await updateVariablesWith(
        vars => {
          if (!vars || typeof vars !== 'object') return vars;
          if (!vars.stat_data || typeof vars.stat_data !== 'object') vars.stat_data = {};
          const existing = vars.stat_data.opening_runtime;
          if (validOpeningRuntime(existing) && existing.session_id !== runtime.session_id) return vars;
          vars.stat_data.opening_runtime = JSON.parse(JSON.stringify(runtime));
          wrote = true;
          return vars;
        },
        scope,
      );
    }
    return wrote;
  }

  async function createLegacyOpeningRuntime(commitKind, stat0) {
    const sessionId =
      'legacy-' +
      ((stat0 && stat0.campaign_id) || 'main') +
      '-' +
      Date.now().toString(36) +
      '-' +
      Math.random().toString(36).slice(2, 6);
    const runtime = {
      schema_version: 1,
      session_id: sessionId,
      identity_revision: 1,
      phase: 'preparing',
      plan: null,
      user_message_id: null,
      assistant_message_id: null,
      last_error: null,
    };
    console.info('[Counterfeit·开场白] 旧档无开局任务标识，进入受限兼容识别（session ' + sessionId + '）');
    const written = await putOpeningRuntime(runtime);
    return written ? runtime : null;
  }

  /** 旧档兼容守卫：0 楼之外存在正式对话内容（开局标记除外）→ 绝不重新开局 */
  function hasRealConversationHistory() {
    try {
      if (typeof getChatMessages !== 'function' || typeof getLastMessageId !== 'function') return false;
      const lastId = getLastMessageId();
      for (let i = 1; i <= lastId; i++) {
        const msg = getChatMessages(i)[0];
        if (!msg || typeof msg.message !== 'string') continue;
        if (isOpeningPayload(msg.message)) continue;
        const text = msg.message.replace(/<[^>]*>/g, '').trim();
        if (text) return true;
      }
    } catch (error) {}
    return false;
  }

  /** 找 user 楼层之后第一条内容有效的 assistant 楼层；/trigger 调用不等于完成 */
  function findAssistantFloorAfter(userMessageId) {
    try {
      if (typeof getLastMessageId !== 'function' || typeof getChatMessages !== 'function') return null;
      const lastId = getLastMessageId();
      for (let id = userMessageId + 1; id <= lastId; id++) {
        const msg = getChatMessages(id)[0];
        if (!msg) continue;
        const isAssistant = msg.role === 'assistant' || msg.is_user === false;
        if (!isAssistant) continue;
        const text = String(msg.message ?? '').replace(/<[^>]*>/g, '').trim();
        if (text) return id;
      }
    } catch (error) {}
    return null;
  }

  // 迁移旧档 commit 后的会话级闩锁：一旦迁移完成，本聊天绝不再挂载开局界面。
  // 真实酒馆里 0 楼刷新若不及时（锚点残留）会让 check() 把刚卸载的界面挂回去；
  // 迁移意味着玩家选择跳过开局，任何"该挂载"信号此后都视为过期。
  let resumeCommitted = false;

  const POV_LABELS = {
    hachiman: '比企谷八幡',
    hachiman_f: '比企谷八幡（性转）',
    yukino: '雪之下雪乃',
    yui: '由比滨结衣',
    laff: '拉芙希妮·都柏林',
    mrs_yukinoshita: '雪之下夫人',
  };

  // 剧情自建参与轨道显示名（与 前端工程/src/Counterfeit/界面/开场白/store.ts PARTICIPATION_LABELS 同步）
  const PARTICIPATION_LABELS = {
    member: '奉仕部第五名部员',
    classmate: '同班旁观者',
    outsider: '场外自由人',
  };

  function buildOpeningMarker(stat, commitKind) {
    if (commitKind === 'resume') return '我已迁移旧档，请从存档中最后一个可观察时刻继续。';
    const campaignId = (stat && stat.campaign_id) || 'main';
    if (campaignId === 'dlc_genderbend_hachiman') {
      const dlcPovKey = (stat && stat.current_pov) || null;
      if (!dlcPovKey) {
        const customName = stat && stat.custom_protagonist && stat.custom_protagonist.name;
        return '我将以自建角色' + (customName ? '“' + customName + '”' : '') + '，进入《错位的日常》。';
      }
      const dlcPovLabel = POV_LABELS[dlcPovKey] || dlcPovKey;
      return '我选择扮演' + dlcPovLabel + '，进入《错位的日常》。';
    }
    if (campaignId === 'dlc_body_swap_mrs_yukinoshita') {
      return stat && stat.current_pov === 'mrs_yukinoshita'
        ? '我选择扮演雪之下夫人的意识，进入《君的名字？》。'
        : '我选择扮演比企谷八幡的意识，进入《君的名字？》。';
    }
    const mode = stat && stat.mode === 'custom' ? 'custom' : stat && stat.mode === 'free' ? 'free' : 'pov';
    const povKey = (stat && stat.current_pov) || 'custom';
    const povLabel = POV_LABELS[povKey] || povKey;
    const customName = stat && stat.custom_protagonist && stat.custom_protagonist.name;
    const customTrack =
      stat && stat.custom_protagonist && stat.custom_protagonist.participation && stat.custom_protagonist.participation.track;
    // free+自建（open+自建）stat.mode='free' 且 current_pov=null → 同样走"我将以自建角色"句式，
    // 否则会生成"我选择扮演custom…"且 isOpeningPayload 判定为 POV 开局（2026-08-07 修复）
    const isCustomPlayer = mode === 'custom' || (mode === 'free' && povKey === 'custom');
    // 不再附加 <counterfeit_opening> 路由标记：尖括号标记会被酒馆消息清洗剥除，
    // 导致编排校验与"开局场景路由"EJS 判断双双失效（首条回复中止 bug 根因）。
    // 路由信息全部冗余于 stat_data 变量与可见句特征（"我选择扮演/我将以自建角色"），
    // 校验与 EJS 一律改用可见句特征，抗清洗且兼容旧存档。
    if (isCustomPlayer) {
      const base = '我将以自建角色' + (customName ? '“' + customName + '”' : '');
      // 剧情模式自建（participation.track 非空）：明示从场景1开始，触发主线场景路由；
      // 旧自建档/开放世界自建无 participation → 维持原句式（开局场景路由按 stat_data 区分）
      if (mode === 'custom' && customTrack) {
        const trackLabel = PARTICIPATION_LABELS[customTrack] || customTrack;
        // T7b：首轮提示写明已确认身份版本（与 opening_runtime.identity_revision / 身份守护同源），
        // 明示模型身份受守护、无自由修改权
        const identityRev =
          stat && stat.opening_runtime && typeof stat.opening_runtime.identity_revision === 'number'
            ? stat.opening_runtime.identity_revision
            : 1;
        return (
          base +
          '参与主线剧情（参与方式：' +
          trackLabel +
          '），请从2013年5月20日的场景1开始故事。已确认身份版本 v' +
          identityRev +
          '，身份与开局设定受守护不可在正文中更改。'
        );
      }
      return base + '开始故事。';
    }
    // 自定义序幕生效（自由世界）：user 标记不带默认日期，开局场景路由以序幕文本为准
    const openingCustom = !!(stat && stat.opening_custom);
    return mode === 'free'
      ? '我选择扮演' + povLabel + (openingCustom ? '，按自定义序幕开始开放世界故事。' : '，从2013年5月20日开始开放世界故事。')
      : '我选择扮演' + povLabel + '，请从2013年5月20日的场景1开始故事。';
  }

  /** 判断一条 user 消息是否为结构化开局消息（可见句特征，抗清洗） */
  function isOpeningPayload(message) {
    const text = String(message || '');
    return text.includes('我选择扮演') || text.includes('我将以自建角色') || text.includes('我已迁移旧档');
  }

  function toast(text, type) {
    try {
      if (typeof showToast === 'function') showToast(text, type || 'info', 4000);
    } catch (error) {}
  }

  /* —— 增强握手：订阅 ready/announce（脚本加载即注册，先于任何请求）—— */
  function ensureOpeningReadySubscription() {
    if (openingReadySubscribed) return true;
    const on = typeof eventOn !== 'undefined' ? eventOn : typeof window !== 'undefined' ? window.eventOn : undefined;
    if (typeof on !== 'function') return false;
    try {
      on('counterfeit_opening_adapter_ready', payload => {
        try {
          if (!payload || typeof payload !== 'object' || typeof payload.session_id !== 'string') return;
          const waiter = openingWaiters.get(payload.session_id);
          // 无活跃等待者（已选定/已完成/非本任务）：迟到结果一律忽略，绝不改写已冻结首轮
          if (!waiter) return;
          if (waiter.fingerprint && typeof payload.input_fingerprint === 'string' && payload.input_fingerprint !== waiter.fingerprint) {
            return;
          }
          waiter.resolve(payload);
        } catch (error) {}
      });
      on('counterfeit_opening_adapter_announce', () => {
        phoneAdapterAnnounced = true;
      });
      openingReadySubscribed = true;
      return true;
    } catch (error) {
      return false;
    }
  }

  /** 发起增强请求（携带完整任务身份：session + 身份版本 + 输入指纹 + 基础方案） */
  function emitOpeningAdapterRequest(sessionId, runtime, plan) {
    if (typeof eventEmit !== 'function') return false;
    try {
      eventEmit('counterfeit_opening_adapter_request', {
        source: 'counterfeit-opening',
        type: 'counterfeit_opening_adapter_request',
        session_id: sessionId,
        identity_revision: runtime.identity_revision || 1,
        input_fingerprint: plan.input_fingerprint,
        campaign_id: plan.campaign_id,
        mainline_scene: plan.mainline_scene,
        base_plan: plan,
        requested_at: new Date().toISOString(),
      });
      return true;
    } catch (error) {
      return false;
    }
  }

  /** 挂载器侧增强方案轻校验：手机侧已做完整约束校验，此处复核任务身份与关键约束 */
  function acceptableEnhancedPlan(candidate, base, sessionId) {
    if (!candidate || typeof candidate !== 'object' || candidate.schema_version !== 1) return false;
    if (candidate.session_id !== sessionId) return false;
    if (!base) return false;
    if (candidate.input_fingerprint !== base.input_fingerprint) return false;
    if (candidate.player_location !== base.player_location) return false;
    if (candidate.date !== base.date) return false;
    if (candidate.contact_mode !== base.contact_mode) return false;
    // T7b：初始人物（known/present/bond 三轴 + 依据）由确定性解析器定档，增强不得改写
    if (JSON.stringify(candidate.initial_characters ?? []) !== JSON.stringify(base.initial_characters ?? [])) return false;
    if (typeof candidate.external_situation !== 'string' || !candidate.external_situation.trim()) return false;
    if (typeof candidate.mainline_connection !== 'string' || !candidate.mainline_connection.trim()) return false;
    return true;
  }

  /* —— 开局进度/选择/重试面板（宿主 DOM；开场 iframe 已卸载，只能在常驻脚本侧提示）—— */
