  /** 30s 未返回的三选面板；返回 Promise<'continue'|'base'|'retry'|'abort'> */
  function showOpeningEnhancePrompt(sessionId, retryCount) {
    return new Promise(resolve => {
      if (!topDoc.body) {
        resolve('base');
        return;
      }
      const panel = buildOpeningPanel(
        'counterfeit-opening-prompt',
        '开局方案解析尚未完成',
        '增强解析超过 30 秒仍未返回。可继续等待、直接使用基础开局，或重试解析。\n使用基础开局后，迟到的增强方案不会改写本轮；基础方案同样满足身份与位置约束。',
      );
      const done = choice => {
        openingPromptAbort = null;
        removeOpeningPanel('counterfeit-opening-prompt');
        resolve(choice);
      };
      openingPromptAbort = () => done('abort');
      appendOpeningButton(panel, '继续等待', () => done('continue'));
      appendOpeningButton(panel, '使用基础开局', () => done('base'));
      appendOpeningButton(panel, retryCount >= 2 ? '重试（将达上限）' : '重试', () => done('retry'));
    });
