  /** 失败重试面板：重试复用同一 user 楼层，绝不重复建楼 */
  function showOpeningRetryPrompt(sessionId, errorText) {
    if (!topDoc.body) return;
    try {
      if (topDoc.getElementById('counterfeit-opening-retry')) return;
      const panel = buildOpeningPanel(
        'counterfeit-opening-retry',
        '自动开局未完成',
        '原因：' + errorText + '\n重试将复用同一个 user 楼层，不会重复建楼；也可以放弃后手动发送第一条消息（不会写入开局变量）。',
      );
      appendOpeningButton(panel, '重试开局', () => {
        removeOpeningPanel('counterfeit-opening-retry');
        void orchestrateFirstReply(lastOpeningCommitKind);
      });
      appendOpeningButton(panel, '放弃自动开局', () => removeOpeningPanel('counterfeit-opening-retry'));
    } catch (error) {}
  }

  /* —— 首条回复落地监视：completed 的唯一判定入口（assistant 消息存在且内容有效）—— */
  function disarmCompletionWatcher() {
    if (openingWatchTimer != null && typeof clearInterval === 'function') {
      try {
        clearInterval(openingWatchTimer);
      } catch (error) {}
    }
    openingWatchTimer = null;
  }
  function armCompletionWatcher(sessionId) {
    disarmCompletionWatcher();
    openingWatchTicks = 0;
    const tick = () => {
      if (openingWatchTimer == null) return;
      openingWatchTicks += 1;
      try {
        const runtime = readOpeningRuntime();
        if (!runtime || runtime.session_id !== sessionId || runtime.phase !== 'generating') {
          disarmCompletionWatcher();
          return;
        }
        const done = runtime.user_message_id != null ? findAssistantFloorAfter(runtime.user_message_id) : null;
        if (done != null) {
          disarmCompletionWatcher();
          void transitionOpeningPhase(sessionId, 'completed', { assistant_message_id: done }).then(
            () => console.info('[Counterfeit·开场白] 首条回复已落地（楼层 ' + done + '），开局完成'),
            () => {},
          );
          return;
        }
        if (openingWatchTicks * OPENING_WATCH_INTERVAL_MS >= OPENING_WATCH_TIMEOUT_MS) {
          disarmCompletionWatcher();
          void transitionOpeningPhase(sessionId, 'failed', { last_error: '首条回复生成超时（5 分钟未落地）' }).then(
            () => {
              toast('首条回复生成超时，可点击重试或手动发送', 'error');
              showOpeningRetryPrompt(sessionId, '首条回复生成超时（5 分钟未落地）');
            },
            () => {},
          );
        }
      } catch (error) {}
    };
    openingWatchTimer = setInterval(tick, OPENING_WATCH_INTERVAL_MS);
  }

  /** generating 恢复：重载/双通知统一在此去重；绝不重复 /trigger（生成可能仍在服务端进行） */
  async function resumeGeneratingRuntime(runtime, alive) {
    const userId = runtime.user_message_id;
    if (userId == null) {
      // 中断在楼层绑定前：回到准备阶段重来
      await transitionOpeningPhase(runtime.session_id, 'preparing', { last_error: null });
      return;
    }
    const done = findAssistantFloorAfter(userId);
    if (done != null) {
      await transitionOpeningPhase(runtime.session_id, 'completed', { assistant_message_id: done });
      console.info('[Counterfeit·开场白] 恢复检测：首条回复已落地（楼层 ' + done + '），开局完成');
      return;
    }
    if (!alive()) return;
    console.info('[Counterfeit·开场白] 任务处于 generating，补挂落地监视（不重复 /trigger）');
    armCompletionWatcher(runtime.session_id);
  }

  /** 认领/建立 user 楼层：手动发送恰在准备期到达时由本协调器认领，防止自动触发再生成一次 */
  async function claimOpeningUserFloor(marker, alive) {
    if (
      typeof getLastMessageId !== 'function' ||
      typeof getChatMessages !== 'function' ||
      typeof createChatMessages !== 'function'
    ) {
      return null;
    }
    const beforeId = getLastMessageId();
    const lastMsg = getChatMessages(beforeId)[0] ?? null;
    if (lastMsg && lastMsg.role === 'user') {
      console.info('[Counterfeit·开场白] 认领既有 user 楼层（' + beforeId + '）为本轮开局楼层');
      return { id: beforeId, claimed: true };
    }
    await createChatMessages([{ role: 'user', message: marker }], { refresh: 'affected' });
    if (alive && !alive()) return null;
    const newId = getLastMessageId();
    if (newId <= beforeId) {
      console.error('[Counterfeit·开场白] user 消息插入后楼层号未变化');
      return null;
    }
    console.info('[Counterfeit·开场白] 已插入开局 user 消息（楼层 ' + newId + '）');
    return { id: newId, claimed: false };
  }

  async function orchestrateFirstReply(commitKind) {
    if (orchestratingToken) return;
    const entryToken = {}; // 本次编排的闩代次：finally 只在代次仍属自己时释放
    orchestratingToken = entryToken;
    lastOpeningCommitKind = commitKind || lastOpeningCommitKind;
    const epoch = chatEpoch;
    const alive = () => epoch === chatEpoch;
    let sessionId = null;
    try {
      // —— 1) 读取开局任务（chat 级权威，0 楼镜像兜底）与 0 楼基线 ——
      let runtime = readOpeningRuntime();
      let stat0 =
        typeof getVariables === 'function'
          ? (getVariables({ type: 'message', message_id: 0 }) || {}).stat_data ?? null
          : null;

      if (validOpeningRuntime(runtime)) {
        sessionId = runtime.session_id;
        // —— 2) 已完成 / 生成中恢复（常驻脚本重载、postMessage 与轮询重复通知统一去重）——
        if (runtime.phase === 'completed') return;
        if (runtime.phase === 'generating') {
          await resumeGeneratingRuntime(runtime, alive);
          return;
        }
      } else {
        // —— 3) 旧档兼容识别（无 session_id）：发现正式历史对话绝不重新开局 ——
        if (hasRealConversationHistory()) {
          console.info('[Counterfeit·开场白] 旧档存在正式历史对话，按兼容策略不重新开局');
          return;
        }
        runtime = await createLegacyOpeningRuntime(commitKind, stat0);
        if (!runtime) return;
        sessionId = runtime.session_id;
        // 旧档识别刚把 opening_runtime 写入 0 楼：重读基线，确保后续楼层镜像复制带上运行时
        stat0 =
          typeof getVariables === 'function'
            ? (getVariables({ type: 'message', message_id: 0 }) || {}).stat_data ?? null
            : null;
      }
      if (!alive() || !sessionId) return;

      // —— 4) 输入版本校验：chat 级与 0 楼方案指纹不一致 = 提交后输入被改动，拒绝启动 ——
      const floorRuntime = readFloorOpeningRuntime(0);
      if (
        floorRuntime &&
        floorRuntime.session_id === sessionId &&
        runtime.plan &&
        floorRuntime.plan &&
        floorRuntime.plan.input_fingerprint !== runtime.plan.input_fingerprint
      ) {
        await transitionOpeningPhase(sessionId, 'failed', {
          last_error: '开局输入版本与提交时不一致，已中止自动开局',
        });
        toast('开局输入版本已变化，自动开局已中止，请重新提交开局', 'error');
        return;
      }

      // —— 5) 就绪闸（O03）：自建主线必须有经校验的方案；绝不静默走 J 班默认入口 ——
      const needsPlan =
        !runtime.plan && stat0 && stat0.mode === 'custom' && (stat0.campaign_id || 'main') === 'main';
      if (!runtime.plan && needsPlan) {
        await transitionOpeningPhase(sessionId, 'failed', {
          last_error: '缺少可用开局方案（自建主线必须有经校验的基础/增强方案）',
        });
        toast('缺少可用开局方案，自动开局已中止', 'error');
        return;
      }

      // —— 6) 进入准备阶段（ready/failed → preparing）——
      if (runtime.phase !== 'preparing') {
        const moved = await transitionOpeningPhase(sessionId, 'preparing', { last_error: null });
        if (!moved) return;
        runtime = moved;
      }
      if (!alive()) return;

      // —— 7) 增强握手：先登记等待者再发请求；手机未就绪保留基础方案，绝不无限等待 ——
      let chosenPlan = runtime.plan;
      if (chosenPlan && phoneAdapterAnnounced && ensureOpeningReadySubscription() && typeof eventEmit === 'function') {
        renderOpeningProgress('正在准备开局方案：解析服务增强中（30 秒未返回可选择基础开局）…');
        let retryCount = 0;
        let needEmit = true; // 仅首圈与「重试」重发请求；「继续等待」只是重新等待，绝不重发（重发会作废手机端在途调用）
        for (;;) {
          // 先订阅（登记 waiter）再发请求（§4.3）；同步回传也不会丢
          const waiter = { resolve: null, fingerprint: chosenPlan.input_fingerprint };
          const resultPromise = new Promise(resolve => {
            waiter.resolve = resolve;
          });
          openingWaiters.set(sessionId, waiter);
          if (needEmit) {
            emitOpeningAdapterRequest(sessionId, runtime, chosenPlan);
            needEmit = false;
          }
          const timeoutPromise = new Promise(resolve => {
            setTimeout(() => resolve(null), OPENING_ENHANCE_WAIT_MS);
          });
          const result = await Promise.race([resultPromise, timeoutPromise]);
          openingWaiters.delete(sessionId);
          if (!alive()) return;
          if (result && result.ok === true && acceptableEnhancedPlan(result.plan, chosenPlan, sessionId)) {
            chosenPlan = result.plan;
            break;
          }
          if (result && result.ok === false && result.error === 'model-not-configured') {
            console.info('[Counterfeit·开场白] 解析服务无模型配置，采用基础开局方案');
            break;
          }
          if (result && result.ok === true) {
            console.warn('[Counterfeit·开场白] 增强方案未通过任务身份/约束校验，忽略');
          }
          const choice = await showOpeningEnhancePrompt(sessionId, retryCount);
          if (!alive() || choice === 'abort') return;
          if (choice === 'base') break;
          if (choice === 'retry') {
            retryCount += 1;
            if (retryCount >= 3) {
              toast('增强解析多次未成功，已改用基础开局方案', 'info');
              break;
            }
            needEmit = true; // 仅「重试」以同一任务身份重发请求
            continue;
          }
          // continue：玩家明确选择继续等待——仅重新登记 waiter 再等待 30 秒，绝不重发请求
        }
        removeOpeningProgress();
      }
      if (!alive()) return;

      // —— 8) 写回选定方案并进入 ready（仅当前任务可写回）——
      const readyRuntime = await transitionOpeningPhase(sessionId, 'ready', { plan: chosenPlan, last_error: null });
      if (!readyRuntime || !alive()) return;

      // —— 9) 认领/建立 user 楼层 ——
      const marker = buildOpeningMarker(stat0, commitKind);
      const floor = await claimOpeningUserFloor(marker, alive);
      if (!floor) {
        await transitionOpeningPhase(sessionId, 'failed', { last_error: '开局 user 楼层建立失败' });
        toast('开局消息插入失败，可点击重试或手动发送第一条消息', 'error');
        showOpeningRetryPrompt(sessionId, '开局 user 楼层建立失败');
        return;
      }

      // —— 10) 复制 0 楼变量基线到 user 楼层（MVU 未自动快照时兜底）——
      try {
        if (stat0 && typeof updateVariablesWith === 'function') {
          const statCopy = JSON.parse(JSON.stringify(stat0));
          await updateVariablesWith(
            vars => {
              vars.stat_data = statCopy;
              return vars;
            },
            { type: 'message', message_id: floor.id },
          );
        }
      } catch (error) {
        console.warn('[Counterfeit·开场白] user 楼层变量基线复制失败（不阻断生成）：', error);
      }

      // —— 11) generating：绑定 user 楼层 → 挂落地监视 → /trigger ——
      const generating = await transitionOpeningPhase(sessionId, 'generating', { user_message_id: floor.id });
      if (!generating || !alive()) return;
      delete failedAutoRetries[sessionId];
      armCompletionWatcher(sessionId);
      if (typeof triggerSlash === 'function') {
        console.info('[Counterfeit·开场白] 通过 /trigger 生成首条回复…');
        await triggerSlash('/trigger');
        console.info('[Counterfeit·开场白] /trigger 已调用，等待首条回复落地（调用不等于完成）');
      } else {
        disarmCompletionWatcher();
        await transitionOpeningPhase(sessionId, 'failed', { last_error: '缺少 triggerSlash API' });
        toast('开局完成，但酒馆助手缺少 /trigger API；请点击重试或手动发送', 'error');
        showOpeningRetryPrompt(sessionId, '缺少 /trigger API');
      }
    } catch (error) {
      console.error('[Counterfeit·开场白] 自动首条回复失败：', error);
      toast('自动首条回复失败，可重试或手动发送第一条消息', 'error');
      if (sessionId) {
        try {
          await transitionOpeningPhase(sessionId, 'failed', {
            last_error: error instanceof Error ? error.message : String(error),
          });
        } catch (inner) {}
        showOpeningRetryPrompt(sessionId, error instanceof Error ? error.message : String(error));
      }
    } finally {
      // 代次校验：CHAT_CHANGED 强释后若已有新编排持闩，旧编排不得清掉新闩
      if (orchestratingToken === entryToken) orchestratingToken = null;
      removeOpeningProgress();
    }
  }

  // 快速通道：commit 完成时 iframe 的通知
  window.top.addEventListener('message', event => {
    const data = event && event.data;
    if (!data || data.source !== 'counterfeit-opening' || data.type !== 'commit-done') return;
    console.info('[Counterfeit·开场白] 收到 commit-done 通知，编排首条回复');
    // 迁移旧档：存档已直接写入，开局界面没有继续停留的意义——立即卸载 iframe，
    // 让玩家直接回到酒馆主界面（否则要等 check() 轮询周期才发现占位符消失）。
    if (data.commitKind === 'resume') {
      // 迁移表格延迟持久化：迁移期插件提交模型要求存在 AI 楼层（commit 写聊天记录），
      // 此时尚无——SaveImportScreen 已做 restore 模式运行时导入，这里暂存插件格式数据，
      // 等首条 AI 回复落地后调 importTableAsJson(persist) 正式持久化（消息/检查点模式重载可恢复）。
      if (data.tableSheets && typeof data.tableSheets === 'object') {
        pendingResumeTables = data.tableSheets;
      }
      resumeCommitted = true;
      // 0 楼重渲染若不及时，锚点残留会让轮询把界面挂回去——先摘锚点再上闩锁
      topDoc.querySelector(ANCHOR_SELECTOR)?.remove();
      const doneIframe = topDoc.getElementById(IFRAME_ID);
      if (doneIframe) {
        unbindOpeningViewportListeners();
        doneIframe.remove();
        console.info('[Counterfeit·开场白] 迁移完成，已立即卸载开局界面');
      }
    }
    // 通知与持久化开局任务不一致（旧开局/串档）时拒绝认领
    const currentRuntime = readOpeningRuntime();
    if (data.sessionId && validOpeningRuntime(currentRuntime) && currentRuntime.session_id !== data.sessionId) {
      console.warn('[Counterfeit·开场白] commit-done 的 session 与当前开局任务不一致，忽略该通知');
      return;
    }
    const replyPromise = orchestrateFirstReply(data.commitKind === 'resume' ? 'resume' : 'opening');
    if (data.commitKind === 'resume' && pendingResumeTables) {
      replyPromise.then(() => scheduleResumeTablesPersist(), () => scheduleResumeTablesPersist());
    }
  });

  // 迁移表格持久化：等待 AI 楼层就绪后调 shujuku importTableAsJson（persist 默认开）。
  // 持久化完成后清理暂存；切换聊天时由 CHAT_CHANGED 钩子取消（见文件底部）。
  let pendingResumeTables = null;
  let resumeTablesPersistDone = false;
  function persistResumeTables() {
    if (!pendingResumeTables || resumeTablesPersistDone) return;
    const api = window.parent.AutoCardUpdaterAPI;
    if (!api || typeof api.importTableAsJson !== 'function') return;
    try {
      if (typeof getLastMessageId === 'function' && typeof getChatMessages === 'function') {
        const lastMsg = getChatMessages(getLastMessageId())[0];
        if (!lastMsg || lastMsg.is_user !== false) return;
      }
    } catch (error) {
      return;
    }
    resumeTablesPersistDone = true;
    const data = pendingResumeTables;
    pendingResumeTables = null;
    try {
      Promise.resolve(api.importTableAsJson(JSON.stringify(data))).then(
        ok => console.info('[Counterfeit·迁移] 数据库表格持久化导入结果：', ok),
        err => console.warn('[Counterfeit·迁移] 数据库表格持久化导入失败：', err),
      );
    } catch (error) {
      console.warn('[Counterfeit·迁移] 数据库表格持久化导入失败：', error);
    }
  }
  function scheduleResumeTablesPersist() {
    if (!pendingResumeTables || resumeTablesPersistDone) return;
    let attempts = 0;
    const tick = () => {
      attempts += 1;
      if (resumeTablesPersistDone || !pendingResumeTables) return;
      persistResumeTables();
      if (!resumeTablesPersistDone && attempts < 30) setTimeout(tick, 1000);
    };
    setTimeout(tick, 1500);
  }

  // 兜底通道：轮询检测未完成的开局任务（新任务按状态机恢复；旧档保持 0 楼已提交 + 仅 0 楼判定）
  function detectCommitDone() {
    if (orchestratingToken) return;
    try {
      if (
        typeof getChatMessages !== 'function' ||
        typeof getLastMessageId !== 'function' ||
        typeof getVariables !== 'function'
      )
        return;
      const runtime = readOpeningRuntime();
      if (validOpeningRuntime(runtime)) {
        if (runtime.phase === 'completed') return;
        const stat0 = (getVariables({ type: 'message', message_id: 0 }) || {}).stat_data;
        if (!stat0 || !stat0.mode) return;
        if (runtime.phase === 'failed') {
          // 失败可重试：轮询自动重试有上限；重试面板与 commit-done 通道不受此限
          const count = failedAutoRetries[runtime.session_id] || 0;
          if (count >= OPENING_FAILED_POLL_RETRY_MAX) return;
          failedAutoRetries[runtime.session_id] = count + 1;
        }
        const floor0 = getChatMessages(0)[0];
        const isResume =
          floor0 && typeof floor0.message === 'string' && floor0.message.includes('<counterfeit_resume_capsule');
        console.info('[Counterfeit·开场白] 轮询检测到未完成任务（' + runtime.phase + '），恢复编排');
        void orchestrateFirstReply(isResume ? 'resume' : 'opening');
        return;
      }
      // —— 旧档兼容路径（无 session_id）——
      if (getLastMessageId() !== 0) return;
      const floor0 = getChatMessages(0)[0];
      if (!floor0 || typeof floor0.message !== 'string' || floor0.message.includes('<OpeningUI/>')) return;
      const vars = getVariables({ type: 'message', message_id: 0 });
      if (!vars || !vars.stat_data || !vars.stat_data.mode) return;
      const isResume = floor0.message.includes('<counterfeit_resume_capsule');
      if (isResume) resumeCommitted = true;
      console.info('[Counterfeit·开场白] 轮询检测到 commit 完成（旧档兼容），编排首条回复');
      void orchestrateFirstReply(isResume ? 'resume' : 'opening');
    } catch (error) {}
  }

  // 最后一道兜底：正则失效（锚点没生成）+ 酒馆助手 API 不可用（读不到 0 楼原文）时，
  // shouldMount 恒为 false，上面所有分支都不会触发——玩家只会看到 0 楼裸露的占位符文本。
  // 这里直接在宿主 DOM 里找那段没被正则替换掉的占位符，作为"该挂载但完全没挂载"的证据。
  function detectUnreplacedPlaceholder() {
    if (noticeDismissed) return;
    if (topDoc.getElementById(IFRAME_ID) || topDoc.getElementById(NOTICE_ID)) return;
    if (topDoc.querySelector(ANCHOR_SELECTOR)) return;
